3	import { useEffect, useState } from "react";
4	import { motion, AnimatePresence } from "framer-motion";
5	
6	const PHRASES = ["Ownership Driven", "Without Hiring", "On Demand"];
7	
8	export function Typewriter() {
9	  const [index, setIndex] = useState(0);
10	
11	  useEffect(() => {
12	    const interval = setInterval(() => {
13	      setIndex((prev) => (prev + 1) % PHRASES.length);
14	    }, 2400);
15	    return () => clearInterval(interval);
16	  }, []);
17	
18	  return (
19	    <span className="inline-block min-w-[280px] text-left">
20	      <AnimatePresence mode="wait">
21	        <motion.span
22	          key={index}
23	          initial={{ opacity: 0, y: 12 }}
24	          animate={{ opacity: 1, y: 0 }}
25	          exit={{ opacity: 0, y: -12 }}
26	          transition={{ duration: 0.3, ease: "easeInOut" }}
27	          className="inline-block bg-gradient-to-r from-[#21cfff] to-[#019ae6] bg-clip-text text-transparent"
28	        >
29	          {PHRASES[index]}
30	        </motion.span>
31	      </AnimatePresence>
32	    </span>
33	  );
34	}
