57	export function PortfolioCarousel() {
58	  const [emblaRef, emblaApi] = useEmblaCarousel({ loop: true });
59	  const [selectedIndex, setSelectedIndex] = useState(0);
60	
61	  const scrollPrev = useCallback(() => emblaApi?.scrollPrev(), [emblaApi]);
62	  const scrollNext = useCallback(() => emblaApi?.scrollNext(), [emblaApi]);
63	  const scrollTo = useCallback(
64	    (i: number) => emblaApi?.scrollTo(i),
65	    [emblaApi]
66	  );
67	
68	  useEffect(() => {
69	    if (!emblaApi) return;
70	    const onSelect = () => setSelectedIndex(emblaApi.selectedScrollSnap());
71	    emblaApi.on("select", onSelect);
72	    onSelect();
73	    return () => {
74	      emblaApi.off("select", onSelect);
75	    };
76	  }, [emblaApi]);
77	
78	  return (
79	    <section className="bg-white py-14">
80	      <div className="mx-auto max-w-5xl px-4 sm:px-6 lg:px-8">
81	        <div className="relative">
82	          {/* Embla viewport */}
83	          <div className="overflow-hidden rounded-2xl" ref={emblaRef}>
84	            <div className="flex">
85	              {SLIDES.map((slide) => (
86	                <div
87	                  key={slide.label}
88	                  className="min-w-0 flex-[0_0_100%]"
89	                >
90	                  <div
91	                    className="rounded-2xl overflow-hidden relative"
92	                    style={{ backgroundColor: slide.bgColor }}
93	                  >
94	                    <div className="relative w-full aspect-[16/10] overflow-hidden">
95	                      <Image
96	                        src={slide.imageSrc}
97	                        alt={slide.imageAlt}
98	                        fill
99	                        className="object-cover object-top"
100	                        sizes="(max-width: 768px) 100vw, 900px"
101	                      />
102	                    </div>
103	                    <div className="px-6 py-4">
104	                      <span
105	                        className="text-xl font-semibold font-roobert"
106	                        style={{ color: slide.accentColor }}
107	                      >
108	                        {slide.label}
109	                      </span>
110	                    </div>
111	                  </div>
112	                </div>
113	              ))}
114	            </div>
115	          </div>
116	
117	          {/* Prev arrow */}
118	          <button
119	            onClick={scrollPrev}
120	            aria-label="Previous slide"
121	            className="absolute left-3 top-1/2 -translate-y-1/2 z-10 flex h-10 w-10 items-center justify-center rounded-full border border-[#e5e7eb] bg-white shadow-sm transition-shadow hover:shadow-md"
122	          >
123	            <svg
124	              width="20"
125	              height="20"
126	              fill="none"
127	              viewBox="0 0 24 24"
128	              aria-hidden="true"
129	            >
130	              <path
131	                d="M7.828 11H20v2H7.828l5.364 5.364-1.414 1.414L4 12l7.778-7.778 1.414 1.414L7.828 11Z"
132	                fill="currentColor"
133	                className="text-[#019ae6]"
134	              />
135	            </svg>
136	          </button>
137	
138	          {/* Next arrow */}
139	          <button
140	            onClick={scrollNext}
141	            aria-label="Next slide"
142	            className="absolute right-3 top-1/2 -translate-y-1/2 z-10 flex h-10 w-10 items-center justify-center rounded-full border border-[#e5e7eb] bg-white shadow-sm transition-shadow hover:shadow-md"
143	          >
144	            <svg
145	              width="20"
146	              height="20"
147	              fill="none"
148	              viewBox="0 0 24 24"
149	              aria-hidden="true"
150	            >
151	              <path
152	                d="M16.172 11H4v2h12.172l-5.364 5.364 1.414 1.414L20 12l-7.778-7.778-1.414 1.414L16.172 11Z"
153	                fill="currentColor"
154	                className="text-[#019ae6]"
155	              />
156	            </svg>
157	          </button>
158	        </div>
159	
160	        {/* Dot navigation */}
161	        <div className="mt-5 flex items-center justify-center gap-2">
162	          {SLIDES.map((_, i) => (
163	            <button
164	              key={i}
165	              onClick={() => scrollTo(i)}
166	              aria-label={`Go to slide ${i + 1}`}
167	              className={`h-3 w-3 rounded-full transition-all ${
168	                i === selectedIndex
169	                  ? "bg-[#082753] scale-110"
170	                  : "bg-[#e5e7eb] hover:bg-[#9ca3af]"
171	              }`}
172	            />
173	          ))}
174	        </div>
175	      </div>
176	    </section>
177	  );
178	}
