"use client";

import { useCallback, useEffect, useState } from "react";
import useEmblaCarousel from "embla-carousel-react";
import Image from "next/image";

interface Slide {
  label: string;
  captionColor: string;
  bgColor: string;
  imageSrc: string;
  imageAlt: string;
  imageWidth: number;
  imageHeight: number;
}

const SLIDES: Slide[] = [
  {
    label: "Shopify",
    bgColor: "#fbf2e4",
    captionColor: "#082753",
    imageSrc: "/images/webflow/69662a202a4c0d57bdf2c10b_Home.png",
    imageAlt: "Portfolio Image — Shopify",
    imageWidth: 843,
    imageHeight: 560,
  },
  {
    label: "WordPress",
    bgColor: "#e6fccd",
    captionColor: "#082753",
    imageSrc: "/images/webflow/Travel.png",
    imageAlt:
      "TravelPerk corporate travel management website template built by Boldteq",
    imageWidth: 840,
    imageHeight: 560,
  },
  {
    label: "Figma UI/UX Design",
    bgColor: "rgba(77,161,175,0.1)",
    captionColor: "#082753",
    imageSrc: "/images/webflow/Home-1.png",
    imageAlt: "Dynamic lifestyle brand website template built by Boldteq",
    imageWidth: 843,
    imageHeight: 560,
  },
  {
    label: "Banners",
    bgColor: "rgba(255,138,138,0.08)",
    captionColor: "#082753",
    imageSrc: "/images/webflow/Group-7.png",
    imageAlt: "Beauty and skincare product website template built by Boldteq",
    imageWidth: 807,
    imageHeight: 560,
  },
];

// Duplicate slides for seamless looping
const ALL_SLIDES = [...SLIDES, ...SLIDES];

export function PortfolioCarousel() {
  const [emblaRef, emblaApi] = useEmblaCarousel({
    loop: true,
    align: "start",
    dragFree: false,
  });
  const [selectedIndex, setSelectedIndex] = useState(0);

  const scrollPrev = useCallback(() => emblaApi?.scrollPrev(), [emblaApi]);
  const scrollNext = useCallback(() => emblaApi?.scrollNext(), [emblaApi]);
  const scrollTo = useCallback(
    (i: number) => emblaApi?.scrollTo(i),
    [emblaApi]
  );

  useEffect(() => {
    if (!emblaApi) return;
    const onSelect = () =>
      setSelectedIndex(emblaApi.selectedScrollSnap() % SLIDES.length);
    emblaApi.on("select", onSelect);
    onSelect();
    return () => {
      emblaApi.off("select", onSelect);
    };
  }, [emblaApi]);

  return (
    <section
      style={{
        paddingTop: "20px",
        paddingLeft: "2%",
        paddingRight: "0%",
        paddingBottom: "64px",
        background: "transparent",
      }}
    >
      <div style={{ position: "relative" }}>
        {/* Embla viewport */}
        <div className="overflow-hidden" ref={emblaRef}>
          <div className="flex" style={{ gap: "24px" }}>
            {ALL_SLIDES.map((slide, i) => (
              <div
                key={`${slide.label}-${i}`}
                style={{
                  flex: "0 0 calc(25% - 18px)",
                  minWidth: 0,
                }}
              >
                <div
                  style={{
                    backgroundColor: slide.bgColor,
                    borderRadius: "20px",
                    padding: "10px",
                    overflow: "hidden",
                    aspectRatio: "1 / 1.22",
                    display: "flex",
                    flexDirection: "column",
                  }}
                >
                  <div
                    style={{
                      flex: 1,
                      overflow: "hidden",
                      borderRadius: "12px",
                      position: "relative",
                    }}
                  >
                    <Image
                      src={slide.imageSrc}
                      alt={slide.imageAlt}
                      fill
                      className="object-cover object-top"
                      sizes="25vw"
                    />
                  </div>
                  <div
                    style={{
                      padding: "12px 8px 4px",
                      textAlign: "left",
                      backgroundColor: "transparent",
                      borderRadius: "8px",
                    }}
                  >
                    <span
                      className="font-roobert font-semibold"
                      style={{ color: slide.captionColor, fontSize: "15px" }}
                    >
                      {slide.label}
                    </span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Prev arrow — circular outlined with blue icon */}
        <button
          onClick={scrollPrev}
          aria-label="Previous slide"
          className="absolute left-[-20px] top-1/2 -translate-y-1/2 z-10 flex h-10 w-10 items-center justify-center transition-shadow hover:shadow-md"
          style={{
            borderRadius: "50%",
            border: "2px solid #019ae6",
            backgroundColor: "#fff",
          }}
        >
          <svg
            width="16"
            height="16"
            fill="none"
            viewBox="0 0 24 24"
            aria-hidden="true"
          >
            <path
              d="M7.828 11H20v2H7.828l5.364 5.364-1.414 1.414L4 12l7.778-7.778 1.414 1.414L7.828 11Z"
              fill="#019ae6"
            />
          </svg>
        </button>

        {/* Next arrow */}
        <button
          onClick={scrollNext}
          aria-label="Next slide"
          className="absolute right-[20px] top-1/2 -translate-y-1/2 z-10 flex h-10 w-10 items-center justify-center transition-shadow hover:shadow-md"
          style={{
            borderRadius: "50%",
            border: "2px solid #019ae6",
            backgroundColor: "#fff",
          }}
        >
          <svg
            width="16"
            height="16"
            fill="none"
            viewBox="0 0 24 24"
            aria-hidden="true"
          >
            <path
              d="M16.172 11H4v2h12.172l-5.364 5.364 1.414 1.414L20 12l-7.778-7.778-1.414 1.414L16.172 11Z"
              fill="#019ae6"
            />
          </svg>
        </button>
      </div>

      {/* Dot navigation */}
      <div className="mt-5 flex items-center justify-center gap-2">
        {SLIDES.map((_, i) => (
          <button
            key={i}
            onClick={() => scrollTo(i)}
            aria-label={`Go to slide ${i + 1}`}
            style={{
              height: "12px",
              width: "12px",
              borderRadius: "50%",
              border: "none",
              cursor: "pointer",
              transition: "background-color 0.2s",
              backgroundColor: i === selectedIndex ? "#000" : "#EDF0F2",
              marginBottom: 0,
              padding: 0,
            }}
          />
        ))}
      </div>
    </section>
  );
}

