          </div>
        </div>

        {/* Plan cards — Growth card elevated (no margin-top), Starter/Pro pushed down (margin-top: 42px) */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "1fr 1fr 1fr",
            gap: "16px",
            padding: "0 5px",
            marginBottom: "48px",
            alignItems: "start",
          }}
        >
          {PRICING_PLANS.map((plan) => {
            const price = getPlanPrice(plan, period);
            const link = getPlanCheckoutLink(plan, period);
            const isPopular = plan.popular;

            return (
              <div
                key={plan.id}
                className="flex flex-col"
                style={{
                  ...(isPopular
                    ? {
                        backgroundColor: "#fff",
                        border: "3px solid #21cfff",
                        borderTopStyle: "none",
                        borderRadius: "20px",
                        marginTop: 0,
                        paddingTop: "50px",
                        paddingLeft: "24px",
                        paddingRight: "24px",
                        paddingBottom: "28px",
                        boxShadow: "none",
                      }
                    : {
                        backgroundColor: "#fff",
                        borderRadius: "15px",
                        marginTop: "42px",
                        padding: "28px",
                        boxShadow: "0 0 5px rgba(0,0,0,.1)",
                      }),
                }}
              >
                {isPopular && (
                  <div className="mb-4 flex items-center gap-2">
                    <Image
                      src="/images/webflow/Layer_2.svg"
                      alt="flash icon"
                      width={18}
                      height={18}
                    />
                    <span
                      className="font-bold uppercase tracking-wider"
                      style={{ color: "#21cfff", fontSize: "12px" }}
                    >
                      Most Popular
                    </span>
                  </div>
                )}

                <div style={{ marginBottom: "20px" }}>
                  <h3
                    className="font-roobert font-semibold"
                    style={{
                      fontSize: "20px",
                      marginBottom: "4px",
                      background:
                        "linear-gradient(90deg, #21cfff, #019ae6)",
                      WebkitBackgroundClip: "text",
                      WebkitTextFillColor: "transparent",
                      backgroundClip: "text",
                    }}
                  >
                    {plan.name}
                  </h3>
                  <div className="flex items-baseline gap-2 mb-1">
                    <span
                      className="font-roobert font-bold text-[#082753]"
                      style={{ fontSize: "32px" }}
                    >
                      ${price.toLocaleString()}
                    </span>
                    <span
                      className="text-[#6b7280]"
                      style={{ fontSize: "14px" }}
                    >
                      /month
                    </span>
                    {period !== "monthly" && (
                      <span
                        className="text-[#9ca3af] line-through"
                        style={{ fontSize: "14px" }}
                      >
                        ${plan.monthlyPrice.toLocaleString()}
                      </span>
                    )}
                  </div>
                  <p
                    className="text-[#6b7280]"
                    style={{ fontSize: "14px" }}
                  >
                    {plan.tagline}
                  </p>
                </div>

                <div style={{ marginBottom: "24px" }}>
                  <p
                    className="text-[#9ca3af] font-semibold uppercase tracking-wider"
                    style={{ fontSize: "11px", marginBottom: "12px" }}
                  >
                    {plan.featuresLabel}
                  </p>
                  <ul className="space-y-2">
                    {plan.features.map((f) => (
                      <li key={f} className="flex items-center gap-2">
                        <CheckIcon />
                        <span
                          className="text-[#374151]"
                          style={{ fontSize: "14px" }}
                        >
                          {f}
                        </span>
                      </li>
                    ))}
                  </ul>
                </div>

                <a
                  href={link}
                  className="mt-auto block w-full text-center font-semibold transition-opacity hover:opacity-90"
                  style={{
                    backgroundImage:
                      "linear-gradient(90deg, #21cfff, #019ae6)",
                    borderRadius: ".75rem",
                    padding: ".75rem 1.5rem",
                    fontSize: "14px",
                    color: "#fff",
                    textDecoration: "none",
                  }}
                >
                  {ctaLabel[period]}
                </a>
              </div>
            );
          })}
        </div>

        {/* Comparison table — CSS grid divs, not <table> */}
        <div
          style={{
            borderRadius: "16px",
            border: "1px solid #e5e7eb",
            overflow: "hidden",
          }}
        >
          {/* Header row */}
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "2fr 1fr 1fr 1fr",
              backgroundColor: "#f5f7fa",
              borderBottom: "1px solid #e5e7eb",
            }}
          >
            <div
              className="font-semibold text-[#082753]"
              style={{ padding: "16px 20px", fontSize: "14px" }}
            >
              Basic Features
            </div>
            <div
              className="font-semibold text-[#082753] text-center"
              style={{ padding: "16px", fontSize: "14px" }}
            >
              Starter
            </div>
            <div
              className="font-semibold text-[#019ae6] text-center"
              style={{ padding: "16px", fontSize: "14px" }}
            >
              Growth
            </div>
            <div
              className="font-semibold text-[#019ae6] text-center"
              style={{ padding: "16px", fontSize: "14px" }}
            >
              Pro
            </div>
          </div>

          {/* Data rows */}
          {COMPARISON_TABLE.map((row, i) => (
            <div
              key={row.label}
              style={{
                display: "grid",
                gridTemplateColumns: "2fr 1fr 1fr 1fr",
                borderBottom: "1px solid #21cfff36",
                backgroundColor: i % 2 === 0 ? "#fff" : "#f9fafb",
              }}
            >
              <div
                className="font-medium text-[#082753]"
                style={{ padding: "16px 20px", fontSize: "14px" }}
                dangerouslySetInnerHTML={{
                  __html: row.label.replace(" &\n", " &<br/>"),
                }}
              />
              {(["starter", "growth", "pro"] as const).map((col) => {
                const val = row[col];
                return (
                  <div
                    key={col}
                    className="flex items-center justify-center"
                    style={{ padding: "16px" }}
                  >
                    {val === false ? (
                      <CrossIcon />
                    ) : val === true ? (
                      <span
                        className="font-semibold"
                        style={{ color: "#019ae6" }}
                      >
                        ✓
                      </span>
                    ) : (
                      <span
                        className="text-[#374151] text-center"
                        style={{ fontSize: "14px" }}
                      >
                        {val}
                      </span>
                    )}
                  </div>
                );
              })}
            </div>
          ))}
        </div>

        {/* Custom plan CTA */}
        <div
          className="text-center"
          style={{
            marginTop: "48px",
            borderRadius: "20px",
            backgroundColor: "#082753",
            padding: "32px 48px",
          }}
        >
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr",
              gap: "32px",
              alignItems: "center",
            }}
          >
            <div className="text-left">
              <h2
                className="font-roobert font-semibold text-white"
                style={{
                  fontSize: "32px",
                  lineHeight: "40px",
                  marginBottom: "12px",
                }}
              >
                Need Something More Flexible?
              </h2>
              <p
                className="text-white/70"
                style={{
                  fontSize: "16px",
                  lineHeight: "28px",
                  marginBottom: "24px",
                }}
              >
                Create a custom subscription based on your workload, turnaround
                needs, and workflow.
              </p>
              <div
                style={{
                  display: "flex",
                  flexWrap: "wrap",
                  gap: "12px 24px",
                  marginBottom: "24px",
                }}
              >
                {[
                  "Flexible capacity",
                  "Custom turnaround",
                  "Multiple projects or brands",
                  "Simple monthly pricing",
                ].map((item) => (
                  <div key={item} className="flex items-center gap-2">
                    <Image
                      src="/images/webflow/Group-1.svg"
                      alt="Check Icon"
                      width={16}
                      height={16}
                    />
                    <span
                      className="text-white/80"
                      style={{ fontSize: "14px" }}
                    >
                      {item}
                    </span>
                  </div>
                ))}
              </div>
              <Link
                href="/contact"
                className="inline-flex items-center justify-center text-white font-semibold transition-opacity hover:opacity-90"
                style={{
                  backgroundImage:
                    "linear-gradient(90deg, #21cfff, #019ae6)",
                  borderRadius: ".75rem",
                  padding: ".75rem 2rem",
                  fontSize: "14px",
                  textDecoration: "none",
                }}
              >
                Build Your Custom Plan
              </Link>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
